16	// ─── CSV parsing ────────────────────────────────────────────────────────────
17	
18	function parseCSVLine(line: string): string[] {
19	  const fields: string[] = [];
20	  let current = "";
21	  let inQuotes = false;
22	
23	  for (let i = 0; i < line.length; i++) {
24	    const ch = line[i];
25	    if (inQuotes) {
26	      if (ch === '"') {
27	        if (i + 1 < line.length && line[i + 1] === '"') {
28	          current += '"';
29	          i++;
30	        } else {
31	          inQuotes = false;
32	        }
33	      } else {
34	        current += ch;
35	      }
36	    } else {
37	      if (ch === '"') {
38	        inQuotes = true;
39	      } else if (ch === ",") {
40	        fields.push(current);
41	        current = "";
42	      } else {
43	        current += ch;
44	      }
45	    }
46	  }
47	  fields.push(current);
48	  return fields;
49	}
50	
51	// ─── Address parsing ────────────────────────────────────────────────────────
52	
53	function splitAddresses(field: string): string[] {
54	  const parts: string[] = [];
55	  let current = "";
56	  let inAngle = 0;
57	  let inQuote = false;
58	
59	  for (const ch of field) {
60	    if (ch === '"' && inAngle === 0) {
61	      inQuote = !inQuote;
62	      current += ch;
63	    } else if (ch === "<" && !inQuote) {
64	      inAngle++;
65	      current += ch;
66	    } else if (ch === ">" && !inQuote) {
67	      inAngle = Math.max(0, inAngle - 1);
68	      current += ch;
69	    } else if (ch === "," && inAngle === 0 && !inQuote) {
70	      parts.push(current);
71	      current = "";
72	    } else {
73	      current += ch;
74	    }
75	  }
76	  if (current.trim()) parts.push(current);
77	  return parts;
78	}
79	
80	function parseAddresses(
81	  field: string
82	): Array<{ name: string; email: string }> {
83	  const results: Array<{ name: string; email: string }> = [];
84	  const parts = splitAddresses(field);
85	
86	  for (const part of parts) {
87	    const trimmed = part.trim();
88	    if (!trimmed) continue;
89	
90	    const angleMatch = trimmed.match(/^(.*?)\s*<([^>]+)>/);
91	    if (angleMatch) {
92	      const name = angleMatch[1].replace(/^["']|["']$/g, "").trim();
93	      const email = angleMatch[2].trim().toLowerCase();
94	      if (email.includes("@")) {
95	        results.push({ name, email });
96	      }
97	      continue;
98	    }
99	
100	    const bareMatch = trimmed.match(/[\w.+\-]+@[\w.\-]+\.\w+/);
101	    if (bareMatch) {
102	      const email = bareMatch[0].toLowerCase();
103	      results.push({ name: "", email });
104	    }
105	  }
106	  return results;
107	}
108	
109	function isOwner(email: string): boolean {
110	  return OWNER_ADDRESSES.has(email);
111	}
112	
113	function parseDate(dateStr: string): Date | null {
114	  const d = new Date(dateStr.trim());
115	  return isNaN(d.getTime()) ? null : d;
116	}
117	
118	// ─── Name parsing ───────────────────────────────────────────────────────────
119	
120	interface ClientName {
121	  firstName: string;
122	  lastName: string;
123	}
124	
125	function parseName(raw: string): ClientName {
126	  const trimmed = raw.trim();
127	  if (!trimmed) return { firstName: "", lastName: "" };
128	
129	  // Handle "Last, First" or "Last, First (org)" format
130	  if (trimmed.includes(",")) {
131	    const parts = trimmed.split(",");
132	    const lastName = parts[0].trim();
133	    // Take just the name part, strip any parenthetical suffix
134	    const firstName = parts
135	      .slice(1)
136	      .join(",")
137	      .trim()
138	      .replace(/\s*\(.*\)\s*$/, "")
139	      .replace(/\s*\[.*\]\s*$/, "")
140	      .trim();
141	    return { firstName, lastName };
142	  }
143	
144	  // Handle "First Last" format — strip parenthetical/bracket suffixes
145	  const cleaned = trimmed
146	    .replace(/\s*\(.*\)\s*$/, "")
147	    .replace(/\s*\[.*\]\s*$/, "")
148	    .trim();
149	  const parts = cleaned.split(/\s+/);
150	  if (parts.length === 1) {
151	    return { firstName: parts[0], lastName: "" };
152	  }
153	  const lastName = parts[parts.length - 1];
154	  const firstName = parts.slice(0, -1).join(" ");
155	  return { firstName, lastName };
156	}
157	
158	// ─── Slug / filename generation ─────────────────────────────────────────────
159	
160	function slugify(s: string): string {
161	  return s
162	    .toLowerCase()
163	    .normalize("NFD")
164	    .replace(/[\u0300-\u036f]/g, "") // strip accents
165	    .replace(/[^a-z0-9]+/g, "-")
166	    .replace(/^-+|-+$/g, "");
167	}
168	
169	function makeFilename(
170	  client: ClientName,
171	  email: string,
172	  usedFilenames: Set<string>
173	): string {
174	  let base: string;
175	  if (client.lastName && client.firstName) {
176	    base = slugify(`${client.lastName}-${client.firstName}`);
177	  } else if (client.lastName) {
178	    base = slugify(client.lastName);
179	  } else if (client.firstName) {
180	    base = slugify(client.firstName);
181	  } else {
182	    // Use email local part
183	    const local = email.split("@")[0];
184	    base = slugify(local);
185	  }
186	
187	  if (!base) base = slugify(email.replace("@", "-at-"));
188	
189	  let filename = base;
190	  if (usedFilenames.has(filename)) {
191	    const domain = email.split("@")[1]?.split(".")[0] || "dup";
192	    filename = `${base}-${slugify(domain)}`;
193	  }
194	  // Final dedup with counter
195	  let final = filename;
196	  let counter = 2;
197	  while (usedFilenames.has(final)) {
198	    final = `${filename}-${counter}`;
199	    counter++;
200	  }
201	  usedFilenames.add(final);
202	  return final + ".md";
203	}
204	
205	// ─── Email record types ─────────────────────────────────────────────────────
206	
207	interface EmailRecord {
208	  date: Date;
209	  dateStr: string; // YYYY-MM-DD
210	  subject: string;
211	  direction: "From client" | "To client" | "CC'd";
212	  threadId: string;
213	  messageId: string;
214	}
215	
216	interface ClientData {
217	  csvName: string;
218	  parsedName: ClientName;
219	  email: string;
220	  emails: EmailRecord[];
221	  // Track name from headers in case CSV has none
222	  headerName: string;
223	}
224	
225	// ─── Load CSV ───────────────────────────────────────────────────────────────
226	
227	function loadClients(): Map<string, ClientData> {
228	  const raw = fs.readFileSync(CSV_PATH, "utf-8");
229	  const lines = raw.split("\n").filter((l) => l.trim() !== "");
230	  const clients = new Map<string, ClientData>();
231	
232	  // Skip header
233	  for (let i = 1; i < lines.length; i++) {
234	    const fields = parseCSVLine(lines[i]);
235	    if (fields.length < 2) continue;
236	
237	    const name = fields[0].trim();
238	    const email = fields[1].trim().toLowerCase();
239	    if (!email) continue;
240	
241	    clients.set(email, {
242	      csvName: name,
243	      parsedName: parseName(name),
244	      email,
245	      emails: [],
246	      headerName: "",
247	    });
248	  }
249	
250	  return clients;
251	}
252	
253	// ─── Decode RFC 2047 encoded words ──────────────────────────────────────────
254	
255	function decodeRFC2047(s: string): string {
256	  return s.replace(
257	    /=\?([^?]+)\?([BbQq])\?([^?]*)\?=/g,
258	    (_match, charset, encoding, encoded) => {
259	      try {
260	        if (encoding.toUpperCase() === "B") {
261	          const buf = Buffer.from(encoded, "base64");
262	          return buf.toString(charset.toLowerCase() === "utf-8" ? "utf-8" : "latin1");
263	        } else {
264	          // Q encoding
265	          const decoded = encoded
266	            .replace(/_/g, " ")
267	            .replace(/=([0-9A-Fa-f]{2})/g, (_: string, hex: string) =>
268	              String.fromCharCode(parseInt(hex, 16))
269	            );
270	          return decoded;
271	        }
272	      } catch {
273	        return encoded;
274	      }
275	    }
276	  );
277	}
278	
279	// ─── Process mbox ───────────────────────────────────────────────────────────
280	
281	async function processMbox(
282	  filePath: string,
283	  clients: Map<string, ClientData>
284	): Promise<void> {
285	  const fileStream = fs.createReadStream(filePath, { encoding: "utf-8" });
286	  const rl = readline.createInterface({
287	    input: fileStream,
288	    crlfDelay: Infinity,
289	  });
290	
291	  let inHeaders = false;
292	  let currentFrom = "";
293	  let currentTo = "";
294	  let currentCc = "";
295	  let currentSubject = "";
296	  let currentDate: Date | null = null;
297	  let currentThreadId = "";
298	  let currentMessageId = "";
299	  let lastHeaderKey = "";
300	  let messageCount = 0;
301	  let matchedCount = 0;
302	
303	  function processMessage() {
304	    if (!currentDate) return;
305	
306	    const fromAddrs = parseAddresses(currentFrom);
307	    const toAddrs = parseAddresses(currentTo);
308	    const ccAddrs = parseAddresses(currentCc);
309	
310	    const subject = decodeRFC2047(currentSubject).trim() || "(no subject)";
311	    const dateStr = currentDate.toISOString().split("T")[0];
312	
313	    // Determine if owner sent or received
314	    const ownerIsSender = fromAddrs.some((a) => isOwner(a.email));
315	
316	    let matched = false;
317	
318	    // Check From addresses
319	    for (const addr of fromAddrs) {
320	      const client = clients.get(addr.email);
321	      if (client) {
322	        client.emails.push({
323	          date: currentDate,
324	          dateStr,
325	          subject,
326	          direction: "From client",
327	          threadId: currentThreadId,
328	          messageId: currentMessageId,
329	        });
330	        if (addr.name && !client.headerName) {
331	          client.headerName = addr.name;
332	        }
333	        matched = true;
334	      }
335	    }
336	
337	    // Check To addresses
338	    for (const addr of toAddrs) {
339	      const client = clients.get(addr.email);
340	      if (client) {
341	        // Only mark "To client" if the owner was the sender
342	        const direction = ownerIsSender ? "To client" : "CC'd";
343	        client.emails.push({
344	          date: currentDate,
345	          dateStr,
346	          subject,
347	          direction,
348	          threadId: currentThreadId,
349	          messageId: currentMessageId,
350	        });
351	        if (addr.name && !client.headerName) {
352	          client.headerName = addr.name;
353	        }
354	        matched = true;
355	      }
356	    }
357	
358	    // Check CC addresses
359	    for (const addr of ccAddrs) {
360	      const client = clients.get(addr.email);
361	      if (client) {
362	        client.emails.push({
363	          date: currentDate,
364	          dateStr,
365	          subject,
366	          direction: "CC'd",
367	          threadId: currentThreadId,
368	          messageId: currentMessageId,
369	        });
370	        if (addr.name && !client.headerName) {
371	          client.headerName = addr.name;
372	        }
373	        matched = true;
374	      }
375	    }
376	
377	    if (matched) matchedCount++;
378	  }
379	
380	  for await (const line of rl) {
381	    if (line.startsWith("From ") && /^From \S+ .+ \d{4}$/.test(line)) {
382	      if (inHeaders || currentFrom || currentTo) {
383	        processMessage();
384	      }
385	      inHeaders = true;
386	      currentFrom = "";
387	      currentTo = "";
388	      currentCc = "";
389	      currentSubject = "";
390	      currentDate = null;
391	      currentThreadId = "";
392	      currentMessageId = "";
393	      lastHeaderKey = "";
394	      messageCount++;
395	
396	      if (messageCount % 10000 === 0) {
397	        process.stderr.write(`\rProcessed ${messageCount} messages, ${matchedCount} matched...`);
398	      }
399	      continue;
400	    }
401	
402	    if (!inHeaders) continue;
403	
404	    if (line.trim() === "") {
405	      inHeaders = false;
406	      continue;
407	    }
408	
409	    // Continuation line
410	    if (/^\s/.test(line)) {
411	      const continuation = line.trim();
412	      if (lastHeaderKey === "from") currentFrom += " " + continuation;
413	      else if (lastHeaderKey === "to") currentTo += " " + continuation;
414	      else if (lastHeaderKey === "cc") currentCc += " " + continuation;
415	      else if (lastHeaderKey === "subject") currentSubject += " " + continuation;
416	      continue;
417	    }
418	
419	    const colonIdx = line.indexOf(":");
420	    if (colonIdx === -1) continue;
421	
422	    const key = line.substring(0, colonIdx).toLowerCase();
423	    const value = line.substring(colonIdx + 1).trim();
424	
425	    switch (key) {
426	      case "from":
427	        currentFrom = value;
428	        lastHeaderKey = "from";
429	        break;
430	      case "to":
431	        currentTo = value;
432	        lastHeaderKey = "to";
433	        break;
434	      case "cc":
435	        currentCc = value;
436	        lastHeaderKey = "cc";
437	        break;
438	      case "subject":
439	        currentSubject = value;
440	        lastHeaderKey = "subject";
441	        break;
442	      case "date":
443	        if (!currentDate) currentDate = parseDate(value);
444	        lastHeaderKey = "date";
445	        break;
446	      case "x-gm-thrid":
447	        currentThreadId = value;
448	        lastHeaderKey = "thrid";
449	        break;
450	      case "message-id":
451	        currentMessageId = value;
452	        lastHeaderKey = "message-id";
453	        break;
454	      default:
455	        lastHeaderKey = key;
456	        break;
457	    }
458	  }
459	
460	  // Process last message
461	  processMessage();
462	
463	  process.stderr.write(
464	    `\rProcessed ${messageCount} messages total, ${matchedCount} matched client emails\n`
465	  );
466	}
467	
468	// ─── Generate markdown files ────────────────────────────────────────────────
469	
470	function escapeYaml(s: string): string {
471	  if (/[:"'{}\[\]#&*!|>%@`]/.test(s) || s.trim() !== s) {
472	    return '"' + s.replace(/\\/g, "\\\\").replace(/"/g, '\\"') + '"';
473	  }
474	  return s;
475	}
476	
477	function generateMarkdown(client: ClientData): string {
478	  // Resolve name: prefer CSV name, fall back to header name
479	  let name = client.parsedName;
480	  if (!name.firstName && !name.lastName && client.headerName) {
481	    name = parseName(decodeRFC2047(client.headerName));
482	  }
483	
484	  const lines: string[] = [];
485	
486	  // YAML frontmatter
487	  lines.push("---");
488	  lines.push(`last_name: ${escapeYaml(name.lastName)}`);
489	  lines.push(`first_name: ${escapeYaml(name.firstName)}`);
490	  lines.push(`email: ${escapeYaml(client.email)}`);
491	  lines.push("---");
492	  lines.push("");
493	  lines.push("## Email History");
494	  lines.push("");
495	
496	  if (client.emails.length === 0) {
497	    lines.push("No emails found in archive.");
498	    lines.push("");
499	    return lines.join("\n");
500	  }
501	
502	  // Sort newest to oldest
503	  client.emails.sort((a, b) => b.date.getTime() - a.date.getTime());
504	
505	  // Group by date
506	  let currentDate = "";
507	  for (const email of client.emails) {
508	    if (email.dateStr !== currentDate) {
509	      currentDate = email.dateStr;
510	      lines.push(`### ${currentDate}`);
511	    }
512	    lines.push(`- **Subject:** ${email.subject}`);
513	    lines.push(`  - Direction: ${email.direction}`);
514	    if (email.threadId) {
515	      lines.push(`  - Thread: ${email.threadId}`);
516	    }
517	    if (email.messageId) {
518	      lines.push(`  - Message-ID: ${email.messageId}`);
519	    }
520	    lines.push("");
521	  }
522	
523	  return lines.join("\n");
524	}
525	
526	// ─── Main ───────────────────────────────────────────────────────────────────
527	
528	async function main() {
529	  // Load clients from CSV
530	  console.error("Loading clients from CSV...");
531	  const clients = loadClients();
532	  console.error(`Loaded ${clients.size} client emails`);
533	
534	  // Find mbox files
535	  const entries = fs.readdirSync(MBOX_DIR);
536	  const mboxFiles = entries
537	    .filter((e) => e.endsWith(".mbox"))
538	    .map((e) => path.join(MBOX_DIR, e));
539	
540	  if (mboxFiles.length === 0) {
541	    console.error("No .mbox files found in", MBOX_DIR);
542	    process.exit(1);
543	  }
544	
545	  console.error(`Found ${mboxFiles.length} mbox file(s)`);
546	
547	  // Process each mbox file
548	  for (const file of mboxFiles) {
549	    console.error(`\nProcessing: ${path.basename(file)}`);
550	    await processMbox(file, clients);
551	  }
552	
553	  // Ensure client directory exists
554	  if (!fs.existsSync(CLIENT_DIR)) {
555	    fs.mkdirSync(CLIENT_DIR, { recursive: true });
556	  }
557	
558	  // Generate markdown files
559	  const usedFilenames = new Set<string>();
560	  let filesWritten = 0;
561	  let totalEmails = 0;
562	
563	  for (const [, client] of clients) {
564	    // Resolve name for filename
565	    let name = client.parsedName;
566	    if (!name.firstName && !name.lastName && client.headerName) {
567	      name = parseName(decodeRFC2047(client.headerName));
568	    }
569	
570	    const filename = makeFilename(name, client.email, usedFilenames);
571	    const markdown = generateMarkdown(client);
572	    const filePath = path.join(CLIENT_DIR, filename);
573	
574	    fs.writeFileSync(filePath, markdown, "utf-8");
575	    filesWritten++;
576	    totalEmails += client.emails.length;
577	  }
578	
579	  console.error(`\n=== Results ===`);
580	  console.error(`Client files written: ${filesWritten}`);
581	  console.error(`Total email records: ${totalEmails}`);
582	  console.error(`Output directory: ${CLIENT_DIR}`);
583	}
584	
585	main().catch((err) => {
586	  console.error("Error:", err);
587	  process.exit(1);
588	});
