import * as fs from "node:fs";
import * as readline from "node:readline";
import * as path from "node:path";
import { simpleParser } from "mailparser";

// Search the mbox archive(s) in mbox/ for every email thread that mentions a
// contact anywhere in its raw text (headers OR body), then dump the full
// decoded text of those threads to stdout.
//
// Usage: npm run search-mbox -- client/chelynne-schram2.md
//
// Two passes over the mbox:
//   1. Case-insensitive raw substring search for the contact's address(es);
//      collect the X-GM-THRID of every matching message.
//   2. Re-stream and emit every message whose thread was matched — so full
//      conversation context is captured, not just the messages that happen to
//      re-mention the contact.
// Threads are ordered newest-first; messages within a thread oldest -> newest
// (natural reading order).

const MBOX_DIR = path.resolve(__dirname, "..", "mbox");

// ─── Contact frontmatter ─────────────────────────────────────────────────────

// Extract the contact's email address(es) from a contact markdown file's YAML
// frontmatter. Handles both `email: "x@y.com"` (string) and `emails:` (list).
function readContactEmails(contactPath: string): string[] {
  const raw = fs.readFileSync(contactPath, "utf-8");
  const fmMatch = raw.match(/^---\r?\n([\s\S]*?)\r?\n---/);
  if (!fmMatch) {
    throw new Error(`No YAML frontmatter found in ${contactPath}`);
  }
  const fm = fmMatch[1];
  const lines = fm.split(/\r?\n/);
  const emails: string[] = [];

  const unquote = (s: string): string =>
    s.trim().replace(/^["']|["']$/g, "").trim();

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];

    // Single string form: email: "x@y.com"
    const singleMatch = line.match(/^email:\s*(.+)$/);
    if (singleMatch) {
      const val = unquote(singleMatch[1]);
      if (val.includes("@")) emails.push(val);
      continue;
    }

    // List form:
    //   emails:
    //     - "a@b.com"
    //     - c@d.com
    if (/^emails:\s*$/.test(line)) {
      for (let j = i + 1; j < lines.length; j++) {
        const item = lines[j].match(/^\s*-\s*(.+)$/);
        if (!item) break;
        const val = unquote(item[1]);
        if (val.includes("@")) emails.push(val);

