import { google } from "googleapis";
import { authorize } from "./gmail-auth";

// Slice 1 — Prove Gmail login.
//
// Authenticate (running the one-time browser consent on first run), then make a
// single read-only users.getProfile call and print who we are. That's the Wahoo.
//
//   npm run gmail-login

async function main() {
  console.error("Authorizing with Gmail (read-only)...");
  const auth = await authorize();
  const gmail = google.gmail({ version: "v1", auth });

  const res = await gmail.users.getProfile({ userId: "me" });
  const p = res.data;

  console.log("\n✅  Gmail login succeeded — Wahoo!\n");
  console.log(`  Mailbox:        ${p.emailAddress}`);
  console.log(`  Total messages: ${p.messagesTotal?.toLocaleString()}`);
  console.log(`  Total threads:  ${p.threadsTotal?.toLocaleString()}`);
  console.log(`  History id:     ${p.historyId}`);
}

main().catch((err) => {
  console.error("\n❌  Gmail login failed:\n");
  console.error(err?.message || err);
  process.exit(1);
});

