import * as path from "node:path";
import * as fs from "node:fs/promises";
import { authenticate } from "@google-cloud/local-auth";
import { google, Auth } from "googleapis";

// Source the auth type from googleapis' own re-export so it matches what
// google.gmail() expects. The top-level google-auth-library, the copy bundled
// under googleapis, and the one under @google-cloud/local-auth are the same
// OAuth2Client at runtime but structurally-distinct TS types — hence the
// `as unknown as Auth.OAuth2Client` casts at each package boundary below.
type AuthClient = Auth.OAuth2Client;

// Shared Gmail OAuth for the CRM sync tool.
//
// Uses the official googleapis + @google-cloud/local-auth packages with the
// Desktop-app loopback flow. Read-only scope — the tool only ever reads Gmail
// and writes markdown locally, so it never needs mailbox write access.
//
// Secrets live in a gitignored .secrets/ directory:
//   .secrets/credentials.json  — the OAuth client (downloaded from GCP console)
//   .secrets/token.json        — the saved refresh token (written on first consent)

const SECRETS_DIR = path.resolve(__dirname, "..", ".secrets");
export const CREDENTIALS_PATH = path.join(SECRETS_DIR, "credentials.json");
export const TOKEN_PATH = path.join(SECRETS_DIR, "token.json");

// Read-only: the tool reads mail and writes markdown locally. Nothing more.
const SCOPES = ["https://www.googleapis.com/auth/gmail.readonly"];

// Load a previously-saved refresh token, if one exists, and rebuild a client
// from it — no browser needed on subsequent runs.
async function loadSavedCredentialsIfExist(): Promise<OAuth2Client | null> {
  try {
    const content = await fs.readFile(TOKEN_PATH, "utf-8");
    const credentials = JSON.parse(content);
    return google.auth.fromJSON(credentials) as OAuth2Client;
  } catch {
    return null;
  }
}

// Persist the refresh token so future runs skip the browser consent.
async function saveCredentials(client: OAuth2Client): Promise<void> {
  const content = await fs.readFile(CREDENTIALS_PATH, "utf-8");
  const keys = JSON.parse(content);
  const key = keys.installed || keys.web;
  const payload = JSON.stringify({
    type: "authorized_user",
    client_id: key.client_id,
    client_secret: key.client_secret,
    refresh_token: client.credentials.refresh_token,
  });
  await fs.writeFile(TOKEN_PATH, payload, "utf-8");
}

// Return an authorized OAuth2 client, running the one-time browser consent flow
// only if no saved token exists yet.
export async function authorize(): Promise<OAuth2Client> {
  const saved = await loadSavedCredentialsIfExist();
  if (saved) return saved;

  const client = await authenticate({
    scopes: SCOPES,
    keyfilePath: CREDENTIALS_PATH,
  });

  if (client.credentials) {
    await saveCredentials(client);
  }
  return client;
}

