  try {
    raw = fs.readFileSync(ENV_PATH, "utf-8");
  } catch {
    throw new Error(
      "GMAIL_OAUTH_SECRET is not set and no readable .env exists at the repo " +
        "root. Export GMAIL_OAUTH_SECRET or stream it into .env, then retry."
