    lead = `${contactLabel} sent this message — start the sentence with "${contactLabel}".`;
  } else {
    lead = "Summarize from the perspective of whoever sent it.";
  }
  return [
    "Summarize the following email in ONE concise sentence from Mark's perspective.",
    lead,
    "Describe what the message actually says. No preamble, no quotes, no subject line — output only the single sentence.",
    "",
    `Subject: ${input.subject}`,
    "Email body:",
    body,
  ].join("\n");
}

