// Slice 4 — pure merge/splice of new entries into a contact file.
//
// mergeContact() is the whole writer's brain: it owns the "## Mark's Email
// History" section and nothing else. Everything from "## Email History" onward
// (Heather's mbox data) is preserved byte-for-byte.

export interface FetchedEntry {
  ts: number; // internalDate ms
  dateStr: string; // YYYY-MM-DD
  subject: string;
  direction: string;
  threadId: string;
  messageId: string;
  link: string;
  summary?: string;
}

// Parsed form of an entry already in the file — legacy Cowork entries may lack
// message id / link, so those are optional.
interface Entry {
  ts: number;
  dateStr: string;
  subject: string;
  direction: string;
  summary?: string;
  threadId?: string;
  messageId?: string;
  link?: string;
}

export interface MergeResult {
  content: string;
  added: number;
  status: "written" | "skipped-malformed";
}

const MARK_HEADING_RE = /^##[ \t]+Mark's Email History[ \t]*$/m;
const NEXT_H2_RE = /^##[ \t]+/m;

function parseEntries(markBody: string): Entry[] {
  const entries: Entry[] = [];
  let curDate = "";
  let cur: Entry | null = null;

  const push = () => {
    if (cur) entries.push(cur);
    cur = null;
  };

  for (const line of markBody.split(/\r?\n/)) {
    const date = line.match(/^###\s+(\d{4}-\d{2}-\d{2})/);
    if (date) {
      push();
      curDate = date[1];
      continue;
    }
    const subj = line.match(/^-\s+\*\*Subject:\*\*\s*(.+?)\s*$/);
    if (subj) {
      push();
      cur = {
        ts: Date.parse(`${curDate}T00:00:00Z`),
        dateStr: curDate,
        subject: subj[1],
        direction: "",
      };
      continue;
    }
    if (!cur) continue;
    const dir = line.match(/^\s*-\s*Direction:\s*(.+?)\s*$/);
    if (dir) cur.direction = dir[1];
    const sum = line.match(/^\s*-\s*Summary:\s*(.+?)\s*$/);
    if (sum) cur.summary = sum[1];
    const thr = line.match(/^\s*-\s*Thread:\s*(.+?)\s*$/);
    if (thr) cur.threadId = thr[1];
    const msg = line.match(/^\s*-\s*Message:\s*(.+?)\s*$/);
    if (msg) cur.messageId = msg[1];
    const lnk = line.match(/^\s*-\s*Link:\s*(.+?)\s*$/);
    if (lnk) cur.link = lnk[1];
  }
  push();
  return entries;
}

function renderEntry(e: Entry): string[] {
  const lines = [`- **Subject:** ${e.subject}`, `  - Direction: ${e.direction}`];
  if (e.summary) lines.push(`  - Summary: ${e.summary}`);
  if (e.threadId) lines.push(`  - Thread: ${e.threadId}`);
  if (e.messageId) lines.push(`  - Message: ${e.messageId}`);
  if (e.link) lines.push(`  - Link: ${e.link}`);
  return lines;
}

function renderSection(entries: Entry[]): string {
  const sorted = [...entries].sort((a, b) => b.ts - a.ts);
  const lines: string[] = [];
  let curDate = "";
  for (const e of sorted) {
    if (e.dateStr !== curDate) {
      curDate = e.dateStr;
      lines.push(`### ${curDate}`);
    }
    lines.push(...renderEntry(e));
    lines.push("");
  }
  return lines.join("\n");
}

export function mergeContact(
  existingContent: string,
  fetched: FetchedEntry[],
  _today: string
): MergeResult {
  const headingMatch = existingContent.match(MARK_HEADING_RE);
  if (!headingMatch || headingMatch.index === undefined) {
    return { content: existingContent, added: 0, status: "skipped-malformed" };
  }

  const headingStart = headingMatch.index;
  const afterHeading = headingStart + headingMatch[0].length;

  // The mbox section (if any) starts at the next H2 after the Mark heading.
  const rest = existingContent.slice(afterHeading);
  const nextH2 = rest.match(NEXT_H2_RE);
  const markBody =
    nextH2 && nextH2.index !== undefined ? rest.slice(0, nextH2.index) : rest;
  const tail =
    nextH2 && nextH2.index !== undefined ? rest.slice(nextH2.index) : "";

  const head = existingContent.slice(0, headingStart);

  const existing = parseEntries(markBody);
  const merged: Entry[] = [...existing, ...fetched];
  const added = fetched.length;

  const section = renderSection(merged);
  const content = `${head}## Mark's Email History\n\n${section}\n${tail}`;

  return { content, added, status: "written" };
}

import { describe, it, expect } from "vitest";
import { mergeContact, type FetchedEntry } from "./merge";

// A populated client-style file: frontmatter, a Mark's Email History section
// with one existing entry, and an mbox "## Email History" section that the tool
// must never touch.
const POPULATED = `---
last_name: Blyth
first_name: Don
email: "don@example.com"
last_updated: 2026-02-18
---

## Mark's Email History

### 2025-09-09
- **Subject:** Re: Rose and Crown
  - Direction: From friend
  - Thread: aaa
  - Message: msg-existing

## Email History

### 2021-01-01
- **Subject:** old mbox thing
  - Direction: From client
  - Thread: 123
  - Message-ID: <x@y>
`;

function entry(over: Partial<FetchedEntry>): FetchedEntry {
  return {
    ts: Date.parse("2026-06-26T12:00:00Z"),
    dateStr: "2026-06-26",
    subject: "Lunch?",
    direction: "From friend",
    threadId: "bbb",
    messageId: "msg-new",
    link: "https://mail.example/msg-new",
    ...over,
  };
}

describe("mergeContact", () => {
  it("splices a new entry and leaves the mbox Email History section untouched", () => {
    const r = mergeContact(POPULATED, [entry({})], "2026-07-02");

    expect(r.status).toBe("written");
    expect(r.added).toBe(1);
    // new entry present
    expect(r.content).toContain("### 2026-06-26");
    expect(r.content).toContain("Message: msg-new");
    // existing Mark entry preserved
    expect(r.content).toContain("Message: msg-existing");
    // the entire mbox section, verbatim, still there
    const mbox = POPULATED.slice(POPULATED.indexOf("## Email History"));
    expect(r.content).toContain(mbox);
  });

  it("does not re-add an entry whose Message id is already present", () => {
    const dup = entry({ messageId: "msg-existing", subject: "changed subject", threadId: "aaa" });
    const r = mergeContact(POPULATED, [dup], "2026-07-02");

    expect(r.added).toBe(0);
    // msg-existing appears exactly once
    expect(r.content.split("Message: msg-existing").length - 1).toBe(1);
    // the duplicate's altered subject was not written
    expect(r.content).not.toContain("changed subject");
  });
});

